      if (!Array.isArray(db.pedidos)) db.pedidos = [];
      if (!Array.isArray(db.clientes)) db.clientes = [];
      if (!Array.isArray(db.ordensServico)) db.ordensServico = [];
      if (!Array.isArray(db.lancamentosFinanceiros)) db.lancamentosFinanceiros = [];
