      const totalVendasFiltradas = comissoesFiltradas.reduce((acc, c) => acc + c.totalVenda, 0);
      const totalComissoesGeradasFiltradas = comissoesFiltradas.reduce((acc, c) => acc + c.comissaoValor, 0);

